	if (target.parents('.editor').length) {
		ga('send',
			{
				hitType: 'event',
				eventCategory: 'Editor',
				eventAction: 'Editor Link Clicked',
				eventLabel: window.location.href
			});
	}
	if (target.parents('.GraphicLinks').length) {
		var text = "";
